{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Normalize log training counts by their 95th percentile over observed items, then clip and retain the square root. This tests stronger attenuation of common history items with less sensitivity to extreme counts. Padding and unseen-item features remain zero. The existing checkpoint buffer preserves predictor consistency; embeddings, backbone, readout, loss and optimizer remain fixed.",
      "edits": [
        {
          "find": "    frequency_feature = np.log1p(training_counts)\n    frequency_feature /= max(float(frequency_feature.max()), 1.0)\n    frequency_feature = np.sqrt(frequency_feature)",
          "replace": "    frequency_feature = np.log1p(training_counts)\n    observed_log_frequency = frequency_feature[training_counts > 0.0]\n    frequency_scale = (\n        float(np.percentile(observed_log_frequency, 95.0))\n        if observed_log_frequency.size else 1.0\n    )\n    frequency_feature = np.clip(\n        frequency_feature / max(frequency_scale, 1e-12), 0.0, 1.0\n    )\n    frequency_feature = np.sqrt(frequency_feature)"
        }
      ]
    }
  ],
  "change_summary": "Apply training-only 95th-percentile frequency normalization across all four category models, retaining the existing feature buffer and single-checkpoint prediction."
}
